import WaveletsExt.Utils:BinaryTree
import WaveletsExt.BestBasis: bestbasis_treeselection
# using LinearAlgebra
const L = LocalCosine
using WaveletsExt:Visualizations

function pretty_print_tree(arr::Vector{T}, idx::Int=1, prefix::String="", is_last::Bool=true) where T
    idx > length(arr) && return

    println(prefix, is_last ? "└── " : "├── ", arr[idx])

    left_idx = 2 * idx
    right_idx = 2 * idx + 1

    has_left = left_idx <= length(arr)
    has_right = right_idx <= length(arr)

    if has_left
        pretty_print_tree(arr, left_idx, prefix * (is_last ? "    " : "│   "), !has_right)
    end

    if has_right
        pretty_print_tree(arr, right_idx, prefix * (is_last ? "    " : "│   "), true)
    end
end




